import csv, json
from decimal import Decimal as D

doc = '/work/documents/'
rows = [r for r in csv.DictReader(open(doc + 'bank_operating_q1.csv'))]
inv = [r for r in csv.DictReader(open(doc + 'summit_supply_invoices.csv'))]

# Summit invoice descriptions keyed by date+amount so each check maps to its invoice
ss_desc = {}
for r in inv:
    ss_desc[(r['date'], D(r['amount']))] = r['description']

def blank():
    return {'revenue': D(0), 'payroll': D(0), 'supplies': D(0), 'rent': D(0),
            'other': {'payroll_taxes_adp': D(0), 'software_dentrix': D(0),
                      'utilities_austin_energy': D(0),
                      'summit_supply_consulting_and_maintenance': D(0),
                      'summit_supply_supplies_misc': D(0)}}

M = {'01': blank(), '02': blank(), '03': blank()}
unclassified = []
for r in rows:
    mk, amt, d = r['date'][5:7], D(r['amount']), r['description']
    m = M[mk]
    if 'MERCHANT DEPOSIT' in d:
        m['revenue'] += amt
    elif 'ADP PAYROLL' in d:
        m['payroll'] += amt          # negative
    elif 'ADP TAX' in d:
        m['other']['payroll_taxes_adp'] += amt
    elif 'RENT' in d:
        m['rent'] += amt
    elif 'HENRY SCHEIN' in d or 'PATTERSON' in d:
        m['supplies'] += amt
    elif 'DENTRIX' in d:
        m['other']['software_dentrix'] += amt
    elif 'AUSTIN ENERGY' in d:
        m['other']['utilities_austin_energy'] += amt
    elif 'SUMMIT' in d:
        desc = ss_desc.get((r['date'], amt))
        # bank check date is 2 days after invoice date; try invoice dates
        if desc is None:
            for k, v in ss_desc.items():
                if v is not None and abs((D(str(k[1])) - amt)) == 0:
                    pass
        if desc and 'Supplies' in desc:
            m['other']['summit_supply_supplies_misc'] += amt
        elif desc:
            m['other']['summit_supply_consulting_and_maintenance'] += amt
        else:
            m['other']['summit_supply_consulting_and_maintenance'] += amt
    else:
        unclassified.append(r)

def f(x):
    return float(round(x, 2))

out = {'months': {}}
totals = {'revenue': D(0), 'payroll': D(0), 'supplies': D(0), 'rent': D(0), 'other': D(0)}
for mk in ['01', '02', '03']:
    m = M[mk]
    out['months'][mk] = {'revenue': f(m['revenue']), 'payroll': f(m['payroll']),
                         'supplies': f(m['supplies']), 'rent': f(m['rent']),
                         'other': {k: f(v) for k, v in m['other'].items()}}
    oth = sum(m['other'].values())
    totals['revenue'] += m['revenue']; totals['payroll'] += m['payroll']
    totals['supplies'] += m['supplies']; totals['rent'] += m['rent']; totals['other'] += oth
    net = m['revenue'] + m['payroll'] + m['supplies'] + m['rent'] + oth
    print(mk, 'rev', f(m['revenue']), 'payroll', f(m['payroll']), 'supplies', f(m['supplies']),
          'rent', f(m['rent']), 'other', f(oth), 'NET', f(net))
    for k, v in m['other'].items():
        print('    ', k, f(v))

print('Q1 totals:', {k: f(v) for k, v in totals.items()},
      'NET', f(sum(totals.values())))
print('unclassified rows:', unclassified)

# reconciliation figures
pay_bank = sum(-D(r['amount']) for r in rows if 'ADP PAYROLL' in r['description'])
tax_bank = sum(-D(r['amount']) for r in rows if 'ADP TAX' in r['description'])
reg = [r for r in csv.DictReader(open(doc + 'payroll_register_q1.csv'))]
gross_pp = sum(D(r['gross_per_period']) for r in reg)
print('payroll bank', f(pay_bank), 'tax', f(tax_bank), 'reg gross/period', f(gross_pp), 'x6', f(gross_pp * 6))
json.dump(out, open('/tmp/opencode/close_core.json', 'w'), indent=2)

