import json, csv
d=json.load(open('deliverable/q1_close.json'))
rows=list(csv.DictReader(open('documents/bank_operating_q1.csv')))
def bucket(r):
    a=float(r['amount']); desc=r['description']
    if a>0: return ('revenue',None)
    if 'ADP PAYROLL' in desc: return ('payroll',None)
    if 'HENRY SCHEIN' in desc or 'PATTERSON' in desc: return ('supplies',None)
    if 'PROPERTY MGMT RENT' in desc: return ('rent',None)
    if 'ADP TAX' in desc: return ('other','payroll_taxes_adp')
    if 'DENTRIX' in desc: return ('other','software_dentrix')
    if 'AUSTIN ENERGY' in desc: return ('other','utilities_austin_energy')
    if 'SUMMIT' in desc: return ('other','summit_supply_supplies_misc' if abs(a+4950)<0.005 else 'summit_supply_consulting_and_maintenance')
    return ('UNMAPPED',desc)
agg={}
for r in rows:
    b,k=bucket(r); m=r['date'][5:7]; key=(m,b,k)
    agg[key]=round(agg.get(key,0)+float(r['amount']),2)
bad=0
for m,mo in d['months'].items():
    for b in ('revenue','payroll','supplies','rent'):
        got=agg.get((m,b,None),0.0)
        if got!=mo[b]: bad+=1; print("MISMATCH",m,b,got,mo[b])
    for k,v in mo['other'].items():
        got=agg.get((m,'other',k),0.0)
        if got!=v: bad+=1; print("MISMATCH",m,k,got,v)
unmapped=[k for k in agg if k[1]=='UNMAPPED']
if unmapped: bad+=1; print("UNMAPPED:",unmapped)
print("bucket mismatches:", bad)
for m,mo in d['months'].items():
    assert round(sum(mo['other'].values()),2)==mo['other_total']
    assert round(mo['revenue']+mo['payroll']+mo['supplies']+mo['rent']+mo['other_total'],2)==mo['net_cash_flow']
q=d['q1_totals']
checks=[(sum(d['months'][m][b] for m in d['months']),q[b]) for b in ('revenue','payroll','supplies','rent')]
checks.append((round(sum(d['months'][m]['other_total'] for m in d['months']),2),q['other']))
checks.append((round(sum(d['months'][m]['net_cash_flow'] for m in d['months']),2),q['net_cash_flow']))
print("q1 totals ok:", all(round(a,2)==round(e,2) for a,e in checks), checks)
print("ALL CHECKS PASS" if bad==0 else "FAILURES PRESENT")
EOF

